function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'MKAverage' || !Array.isArray(args[0]) || args[0].length !== 2) return 'Start with MKAverage(m, k).';
  const [m, k] = args[0];
  if (!Number.isInteger(m) || m < 3 || m > 100000) return 'm is an integer from 3 to 10^5.';
  if (!Number.isInteger(k) || k < 1 || 2 * k >= m) return 'k is at least 1 and 2 * k is less than m.';
  if (operations.length - 1 > 100000) return 'At most 10^5 calls after the constructor.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] === 'addElement') {
      const num = Array.isArray(args[i]) && args[i].length === 1 ? args[i][0] : null;
      if (!Number.isInteger(num) || num < 1 || num > 100000) return 'addElement takes one integer from 1 to 10^5.';
    } else if (operations[i] === 'calculateMKAverage') {
      if (!Array.isArray(args[i]) || args[i].length !== 0) return 'calculateMKAverage takes no arguments.';
    } else {
      return 'Only addElement and calculateMKAverage can follow the constructor.';
    }
  }
  return null;
}

