class MKAverage {
  constructor(m, k) {
    this.m = m;
    this.k = k;
    this.maxValue = 100000;
    this.count = new Array(this.maxValue + 1).fill(0);
    this.total = new Array(this.maxValue + 1).fill(0);
    this.stream = [];
    this.head = 0;
  }

  update(value, delta) {
    for (let i = value; i <= this.maxValue; i += i & -i) {
      this.count[i] += delta;
      this.total[i] += delta * value;
    }
  }

  sumOfSmallest(t) {
    let position = 0;
    let taken = 0;
    let sum = 0;
    for (let step = 1 << 16; step > 0; step >>= 1) {
      const next = position + step;
      if (next <= this.maxValue && taken + this.count[next] < t) {
        position = next;
        taken += this.count[next];
        sum += this.total[next];
      }
    }
    return sum + (t - taken) * (position + 1);
  }

  addElement(num) {
    this.stream.push(num);
    this.update(num, 1);
    if (this.stream.length - this.head > this.m) {
      this.update(this.stream[this.head], -1);
      this.head++;
    }
  }

  calculateMKAverage() {
    if (this.stream.length - this.head < this.m) return -1;
    const middle = this.sumOfSmallest(this.m - this.k) - this.sumOfSmallest(this.k);
    return Math.floor(middle / (this.m - 2 * this.k));
  }
}

