class MKAverage {
  constructor(m, k) {
    this.m = m;
    this.k = k;
    this.all = [];
  }
  addElement(num) {
    this.all.push(num);
  }
  calculateMKAverage() {
    if (this.all.length < this.m) return -1;
    const recent = this.all.slice(this.all.length - this.m).sort((a, b) => a - b);
    const kept = recent.slice(this.k, this.m - this.k);
    let sum = 0;
    for (const value of kept) sum += value;
    return Math.floor(sum / kept.length);
  }
}

