function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const m = size === 'large' ? [3, 20, 150, 400][pick(0, 3)] : pick(3, 7);
  const k = pick(1, Math.floor((m - 1) / 2));
  const top = [3, 20, 1000, 100000][pick(0, 3)];
  const calls = size === 'large' ? 499 : pick(1, 18);
  const calcRate = size === 'large' ? 0.25 : 0.35;
  const operations = ['MKAverage'];
  const args = [[m, k]];
  for (let i = 0; i < calls; i++) {
    if (rand() < calcRate) {
      operations.push('calculateMKAverage');
      args.push([]);
    } else {
      operations.push('addElement');
      args.push([pick(1, top)]);
    }
  }
  return [operations, args];
}
